//#region src/lib/Player/Planet.ts
var Planet = class {
	mesh;
	position = new Vector3();
	radius = .25;
	color;
	rotation = 0;
	trail = null;
	showTrail = false;
	constructor(color, initialPosition, showTrail = false) {
		this.color = new Color(color);
		this.showTrail = showTrail;
		const geometry = new SphereGeometry(this.radius, 32, 32);
		const material = new MeshBasicMaterial({ color: this.color });
		this.mesh = new Mesh(geometry, material);
		this.mesh.renderOrder = 110;
		if (initialPosition) {
			this.position.copy(initialPosition);
			this.mesh.position.copy(initialPosition);
		}
		if (this.showTrail) this.trail = new PlanetTrail(this.color, this.radius);
	}
	update(deltaTime, currentTime = 0) {
		this.mesh.position.copy(this.position);
	}
	/** Feed computed trail positions (Float64Array of XY pairs) to the trail renderer */
	setTrailPoints(xy) {
		if (this.trail) this.trail.setPoints(xy);
	}
	render(scene) {
		if (!scene.children.includes(this.mesh)) scene.add(this.mesh);
		if (this.trail && !scene.children.includes(this.trail.mesh)) scene.add(this.trail.mesh);
	}
	removeFromScene(scene) {
		if (scene.children.includes(this.mesh)) scene.remove(this.mesh);
		if (this.trail && scene.children.includes(this.trail.mesh)) scene.remove(this.trail.mesh);
	}
	setRadius(r) {
		this.radius = r;
		this.mesh.geometry.dispose();
		this.mesh.geometry = new SphereGeometry(r, 32, 32);
		if (this.trail) this.trail.setPlanetRadius(r);
	}
	clearTrail() {
		if (this.trail) this.trail.clear();
	}
	moveTo(target) {
		this.position.copy(target);
		this.mesh.position.copy(target);
	}
	dispose() {
		if (this.mesh) {
			this.mesh.geometry.dispose();
			if (Array.isArray(this.mesh.material)) this.mesh.material.forEach((m) => m.dispose());
			else this.mesh.material.dispose();
		}
		if (this.trail) this.trail.dispose();
	}
};
