//#region src/lib/Player/effects/ShakeScreen.ts
var ShakeScreen = class ShakeScreen {
	fgState = ShakeScreen.createInactive();
	bgState = ShakeScreen.createInactive();
	shakeOffset = new Vector2(0, 0);
	static createInactive() {
		return {
			active: false,
			startTime: 0,
			duration: 0,
			strength: 0,
			intensity: 0,
			fadeOut: false,
			ease: "Linear",
			vibrato: 0
		};
	}
	startShake(currentTime, strength, intensity, duration, ease, fadeOut, plane) {
		const state = plane === "FG" ? this.fgState : this.bgState;
		state.active = true;
		state.startTime = currentTime;
		state.strength = strength;
		state.intensity = intensity;
		state.duration = duration;
		state.ease = ease || "Linear";
		state.fadeOut = fadeOut;
		state.vibrato = Math.max(1, Math.round(20 * intensity));
	}
	update(currentTime) {
		if (!this.fgState.active && !this.bgState.active) {
			this.shakeOffset.set(0, 0);
			return this.shakeOffset;
		}
		let offsetX = 0;
		let offsetY = 0;
		for (const state of [this.fgState, this.bgState]) {
			if (!state.active) continue;
			const elapsed = currentTime - state.startTime;
			let progress = state.duration > 0 ? elapsed / state.duration : 1;
			if (progress >= 1) {
				state.active = false;
				continue;
			}
			if (progress < 0) progress = 0;
			let envelope;
			const easeName = state.ease || "Linear";
			if (easeName === "Linear") envelope = 1;
			else if (easeName.startsWith("InOut")) {
				const t = EasingFunctions[easeName] ? EasingFunctions[easeName](progress) : progress;
				envelope = t < .5 ? t * 2 : 2 - t * 2;
			} else if (easeName.startsWith("Out")) envelope = 1 - (EasingFunctions[easeName] ? EasingFunctions[easeName](progress) : progress);
			else envelope = EasingFunctions[easeName] ? EasingFunctions[easeName](progress) : progress;
			if (state.fadeOut) envelope *= 1 - progress;
			const amp = state.strength * envelope;
			const vibrato = state.vibrato;
			const phase = progress * vibrato * Math.PI * 2;
			const seed = state.startTime * 1e3;
			offsetX += amp * Math.sin(phase * 1.3 + seed * .1);
			offsetY += amp * Math.sin(phase * .7 + seed * .3 + 1.2);
		}
		this.shakeOffset.set(offsetX, offsetY);
		return this.shakeOffset;
	}
	getShakeOffset() {
		return this.shakeOffset;
	}
	stop() {
		this.fgState.active = false;
		this.bgState.active = false;
		this.shakeOffset.set(0, 0);
	}
};
