					const newShapeKey = `${i > 0 ? (prevResolved || 0) - 180 : -180}_${resolved || 0}_${this.levelData.tiles[i]?.direction === 999}_${newTrackStyle}`;
					this.instancedMeshManager.updateTile(i, newShapeKey, tileMesh.position, tileMesh.rotation, tileMesh.scale, rendered.color, rendered.bgcolor, rendered.opacity, true, texSeed, tileMesh.userData.floorIconType ?? 0, tileMesh.userData.floorIconAngle ?? 0);
